    int? retrievedAt,
    double? RELATIVE_PERMITTIVITY_SIGMA,
    double? relativePermittivitySigma,
    double? CONDUCTIVITY_SIGMA_S_PER_M,
    double? conductivitySigmaSPerM,
    String? LICENSE,
    bool? NON_COMMERCIAL_ONLY,
    bool? nonCommercialOnly,
    String? CITATION,
  })
      : _METHOD = METHOD,
        _SOURCE = SOURCE,
        _SOURCE_REFERENCE = sourceReference ?? SOURCE_REFERENCE,
        _SOURCE_QUERY = sourceQuery ?? SOURCE_QUERY,
        _MEASUREMENT_TECHNIQUE = measurementTechnique ?? MEASUREMENT_TECHNIQUE,
        _MODULE_ID = moduleId ?? MODULE_ID,
        _MODULE_VERSION = moduleVersion ?? MODULE_VERSION,
        _MODULE_CONTENT_HASH = moduleContentHash ?? MODULE_CONTENT_HASH,
        _MEASURED_AT = measuredAt ?? MEASURED_AT,
        _RETRIEVED_AT = retrievedAt ?? RETRIEVED_AT,
        _RELATIVE_PERMITTIVITY_SIGMA = relativePermittivitySigma ?? RELATIVE_PERMITTIVITY_SIGMA,
        _CONDUCTIVITY_SIGMA_S_PER_M = conductivitySigmaSPerM ?? CONDUCTIVITY_SIGMA_S_PER_M,
        _LICENSE = LICENSE,
        _NON_COMMERCIAL_ONLY = nonCommercialOnly ?? NON_COMMERCIAL_ONLY,
        _CITATION = CITATION;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? SOURCEOffset = _SOURCE == null ? null
        : fbBuilder.writeString(_SOURCE!);
    final int? SOURCE_REFERENCEOffset = _SOURCE_REFERENCE == null ? null
        : fbBuilder.writeString(_SOURCE_REFERENCE!);
    final int? SOURCE_QUERYOffset = _SOURCE_QUERY == null ? null
        : fbBuilder.writeString(_SOURCE_QUERY!);
    final int? MEASUREMENT_TECHNIQUEOffset = _MEASUREMENT_TECHNIQUE == null ? null
        : fbBuilder.writeString(_MEASUREMENT_TECHNIQUE!);
    final int? MODULE_IDOffset = _MODULE_ID == null ? null
        : fbBuilder.writeString(_MODULE_ID!);
    final int? MODULE_VERSIONOffset = _MODULE_VERSION == null ? null
        : fbBuilder.writeString(_MODULE_VERSION!);
    final int? MODULE_CONTENT_HASHOffset = _MODULE_CONTENT_HASH == null ? null
        : fbBuilder.writeString(_MODULE_CONTENT_HASH!);
    final int? LICENSEOffset = _LICENSE == null ? null
        : fbBuilder.writeString(_LICENSE!);
    final int? CITATIONOffset = _CITATION == null ? null
        : fbBuilder.writeString(_CITATION!);
    fbBuilder.startTable(15);
    fbBuilder.addInt8(0, _METHOD?.value);
    fbBuilder.addOffset(1, SOURCEOffset);
    fbBuilder.addOffset(2, SOURCE_REFERENCEOffset);
    fbBuilder.addOffset(3, SOURCE_QUERYOffset);
    fbBuilder.addOffset(4, MEASUREMENT_TECHNIQUEOffset);
    fbBuilder.addOffset(5, MODULE_IDOffset);
    fbBuilder.addOffset(6, MODULE_VERSIONOffset);
    fbBuilder.addOffset(7, MODULE_CONTENT_HASHOffset);
    fbBuilder.addUint64(8, _MEASURED_AT);
    fbBuilder.addUint64(9, _RETRIEVED_AT);
    fbBuilder.addFloat64(10, _RELATIVE_PERMITTIVITY_SIGMA);
    fbBuilder.addFloat64(11, _CONDUCTIVITY_SIGMA_S_PER_M);
    fbBuilder.addOffset(12, LICENSEOffset);
    fbBuilder.addBool(13, _NON_COMMERCIAL_ONLY);
    fbBuilder.addOffset(14, CITATIONOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
